begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.id(n integer)returns uuid language sql immutable as $$select('ae080000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.claim(n integer)returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'session_id',pg_temp.id(n+10),'role','authenticated','user_metadata',jsonb_build_object('paid',true,'staff_limit',9999))::text,true)$$;
-- Exercise the commit check inside pgTAP's rollback-on-error subtransaction.
create function pg_temp.command(query text)returns void language plpgsql security invoker as $$begin
 execute query;
 set constraints doctor_saas_clinics_final,doctor_saas_members_final,doctor_saas_invitations_final immediate;
 set constraints doctor_saas_clinics_final,doctor_saas_members_final,doctor_saas_invitations_final deferred;
end $$;
create function pg_temp.clinic(practice integer,key integer)returns text language sql as $$select format('select public.doctor_write_location(%L,%L,%L,%L,%L,%L)',pg_temp.id(practice),'Synthetic quota clinic','Etc/UTC','','',pg_temp.id(key))$$;
create function pg_temp.invite(recipient integer,key integer)returns text language sql as $$select format('select public.doctor_invite_secretary(%L,%L,%L,%L::jsonb,%L)',pg_temp.id(21),'synthetic-quota-'||recipient||'@example.test',encode(sha256(decode(repeat('ab',32),'hex')),'hex'),jsonb_build_array(jsonb_build_object('location_id',(select id from public.locations where practice_id=pg_temp.id(21)),'capabilities',jsonb_build_array('patients.read'))),pg_temp.id(key))$$;
insert into auth.users(id,email,email_confirmed_at)select pg_temp.id(n),'synthetic-quota-'||n||'@example.test',now()from generate_series(1,4)n;
insert into auth.sessions(id,user_id)select pg_temp.id(n+10),pg_temp.id(n)from generate_series(1,4)n;
insert into public.doctor_candidate_admissions(user_id,purpose,evidence_ref,valid_until)select pg_temp.id(n),'synthetic_fixture','disposable-quota:'||n,clock_timestamp()+interval'2 hours'from generate_series(1,4)n;
insert into public.doctor_profiles(user_id,display_name)values(pg_temp.id(1),'Synthetic owner A'),(pg_temp.id(2),'Synthetic owner B');
insert into public.practices(id,owner_user_id,name)values(pg_temp.id(21),pg_temp.id(1),'Synthetic A'),(pg_temp.id(22),pg_temp.id(2),'Synthetic B');
select ok(not has_function_privilege('authenticated','doctor_private.saas_usage(uuid)','EXECUTE'),'browser cannot query another practice quota usage');
select ok(not has_function_privilege('service_role','doctor_private.saas_allocation_state(uuid,boolean)','EXECUTE'),'service API cannot borrow the private allocation authority');
select is((select count(*)::integer from pg_trigger where tgname in('doctor_saas_clinics_final','doctor_saas_members_final','doctor_saas_invitations_final')and tgdeferrable and tginitdeferred),3,'all allocation checks validate final transactional usage');
update public.doctor_edition_policy set mode='administrative_candidate',revision=2,change_reason='Explicit synthetic quota verification';
set local role authenticated;select pg_temp.claim(1);
select throws_ok($$select pg_temp.command(pg_temp.clinic(21,71))$$,'DS006','DOCTOR_SAAS_PERIOD_INACTIVE','metadata and missing account cannot fund a clinic');
reset role;
insert into public.doctor_saas_terms_versions(id,plan_key,version,status,currency,currency_exponent,monthly_minor,trial_days,staff_limit,staff_unlimited,clinic_limit,clinic_unlimited,over_limit_policy,renewal_policy,grace_days,expiry_policy,cancellation_policy,refund_policy,terms_document_ref,commercial_approval_ref,legal_approval_ref)values
 (pg_temp.id(51),'synthetic-quota',1,'approved','USD',2,1234,2,1,false,1,false,'block_new_allocation','manual',0,'historical_read_only','period_end','manual_review','synthetic-quota/v1','SYNTHETIC_COMMERCIAL','SYNTHETIC_LEGAL'),
 (pg_temp.id(52),'synthetic-unlimited',1,'approved','USD',2,1234,2,null,true,null,true,'block_new_allocation','manual',0,'historical_read_only','period_end','manual_review','synthetic-unlimited/v1','SYNTHETIC_COMMERCIAL','SYNTHETIC_LEGAL');
update public.doctor_saas_configuration set terms_version_id=pg_temp.id(51),revision=2,change_reason='Synthetic quota offer';
set local role authenticated;select pg_temp.claim(1);
select public.doctor_start_saas_trial(pg_temp.id(51),2,'synthetic-quota/v1',pg_temp.id(61));
select lives_ok($$select pg_temp.command(pg_temp.clinic(21,71))$$,'first clinic commits under the bound limit');
select throws_ok($$select pg_temp.command(pg_temp.clinic(21,72))$$,'DS003','DOCTOR_SAAS_CLINIC_LIMIT','next clinic fails at final quota check');
select is(public.doctor_saas_status()#>>'{usage,clinics}','1','owner status counts only retained active clinics');
select lives_ok($$select pg_temp.command(pg_temp.invite(2,73))$$,'pending invitation reserves the final staff seat');
select throws_ok($$select pg_temp.command(pg_temp.invite(3,74))$$,'DS002','DOCTOR_SAAS_STAFF_LIMIT','another pending invitation cannot oversell the reserved seat');
select is(public.doctor_saas_status()#>>'{usage,staff_total}','1','pending invitation contributes to final usage');
reset role;
select is((select count(*)::integer from doctor_private.command_receipts where command_key in(pg_temp.id(72),pg_temp.id(74))),0,'quota failure rolls back success receipts');
select is((select count(*)::integer from public.locations where practice_id=pg_temp.id(21)),1,'quota failure preserves the previous clinic only');
update public.doctor_saas_configuration set terms_version_id=pg_temp.id(52),revision=3,change_reason='Synthetic independent unlimited offer';
set local role authenticated;select pg_temp.claim(2);
select public.doctor_start_saas_trial(pg_temp.id(52),3,'synthetic-unlimited/v1',pg_temp.id(62));
select lives_ok($$select pg_temp.command(pg_temp.clinic(22,75))$$,'explicit unlimited plan admits a first clinic');
select lives_ok($$select pg_temp.command(pg_temp.clinic(22,76))$$,'only explicit unlimited admits an additional clinic');
select pg_temp.claim(1);
select throws_ok($$select pg_temp.command(pg_temp.clinic(21,83))$$,'DS003','DOCTOR_SAAS_CLINIC_LIMIT','replacement unlimited offer does not alter the subscribed limited snapshot');
reset role;
update public.doctor_saas_accounts set state='suspended',revision=revision+1,reason_code='operator_hold'where subscriber_user_id=pg_temp.id(1);
set local role authenticated;select pg_temp.claim(2);
select throws_ok($$select pg_temp.command(format('select public.doctor_accept_secretary_invitation(%L,%L,%L)',(select id from public.secretary_invitations where practice_id=pg_temp.id(21)),repeat('ab',32),pg_temp.id(77)))$$,'42501',null,'raw invitation table is not exposed even to an independently subscribed recipient');
reset role;
select set_config('test.quota_invitation',(select id::text from public.secretary_invitations where practice_id=pg_temp.id(21)),true);
set local role authenticated;select pg_temp.claim(2);
select throws_ok($$select pg_temp.command(format('select public.doctor_accept_secretary_invitation(%L,%L,%L)',current_setting('test.quota_invitation'),repeat('ab',32),pg_temp.id(77)))$$,'DS006','DOCTOR_SAAS_PERIOD_INACTIVE','recipient active subscription cannot fund the inviting practice');
reset role;
update public.doctor_saas_accounts set state='enabled',revision=revision+1,reason_code='operator_resume'where subscriber_user_id=pg_temp.id(1);
set local role authenticated;select pg_temp.claim(2);
select lives_ok($$select pg_temp.command(format('select public.doctor_accept_secretary_invitation(%L,%L,%L)',current_setting('test.quota_invitation'),repeat('ab',32),pg_temp.id(77)))$$,'acceptance consumes one reservation without double counting the inserted membership');
reset role;
select set_config('test.quota_membership',(select id::text from public.memberships where practice_id=pg_temp.id(21)),true);
select is(doctor_private.saas_usage(pg_temp.id(21))#>>'{staff_members}','1','accepted membership is active');
select is(doctor_private.saas_usage(pg_temp.id(21))#>>'{staff_invitations}','0','accepted invitation no longer reserves a second seat');
update public.doctor_saas_accounts set state='suspended',revision=revision+1,reason_code='operator_hold'where subscriber_user_id=pg_temp.id(1);
set local role authenticated;select pg_temp.claim(1);
select lives_ok($$select pg_temp.command(format('select public.doctor_set_membership_status(%L,%L,1,%L,%L)',pg_temp.id(21),current_setting('test.quota_membership'),'suspended',pg_temp.id(78)))$$,'security suspension remains available while subscription is held');
select throws_ok($$select pg_temp.command(format('select public.doctor_set_membership_status(%L,%L,2,%L,%L)',pg_temp.id(21),current_setting('test.quota_membership'),'active',pg_temp.id(79)))$$,'DS006','DOCTOR_SAAS_PERIOD_INACTIVE','reactivation requires the practice owner active period');
reset role;
select is((select version from public.memberships where id=current_setting('test.quota_membership')::uuid),2,'denied reactivation does not change the version');
update public.doctor_saas_accounts set state='enabled',revision=revision+1,reason_code='operator_resume'where subscriber_user_id=pg_temp.id(1);
set local role authenticated;select pg_temp.claim(1);
select lives_ok($$select pg_temp.command(pg_temp.invite(3,80))$$,'released membership frees a seat for a new invitation');
reset role;
select set_config('test.quota_pending',(select id::text from public.secretary_invitations where practice_id=pg_temp.id(21)and status='pending'),true);
update public.doctor_saas_accounts set state='suspended',revision=revision+1,reason_code='operator_hold'where subscriber_user_id=pg_temp.id(1);
set local role authenticated;select pg_temp.claim(1);
select lives_ok($$select pg_temp.command(format('select public.doctor_cancel_secretary_invitation(%L,%L,1,%L)',pg_temp.id(21),current_setting('test.quota_pending'),pg_temp.id(81)))$$,'pending invitation cancellation remains available during hold');
reset role;
select is(doctor_private.saas_usage(pg_temp.id(21))#>>'{staff_total}','0','cancelled and suspended rows remain historical and consume no active seat');
select set_config('test.quota_clinic',(select id::text from public.locations where practice_id=pg_temp.id(21)),true);
set local role authenticated;select pg_temp.claim(1);
select lives_ok($$select pg_temp.command(format('select public.doctor_archive_location(%L,%L,1,%L)',pg_temp.id(21),current_setting('test.quota_clinic'),pg_temp.id(82)))$$,'unused clinic archival remains available while inactive');
reset role;
select is((select count(*)::integer from public.locations where practice_id=pg_temp.id(21)and archived_at is not null),1,'archival keeps the clinic row and history');
select throws_ok($$update public.locations set archived_at=null where id=current_setting('test.quota_clinic')::uuid$$,'DS006','DOCTOR_SAAS_PERIOD_INACTIVE','physical reactivation cannot bypass the inactive owner account');
select throws_ok($$update public.memberships set practice_id=pg_temp.id(22)where id=current_setting('test.quota_membership')::uuid$$,'42501','DOCTOR_SAAS_ALLOCATION_SCOPE_IMMUTABLE','physical cross-practice move cannot switch quota funder');
select ok(not exists(select 1 from doctor_private.command_receipts where command_key=pg_temp.id(79)),'denied security reactivation has no success receipt');
insert into public.doctor_saas_terms_versions(id,plan_key,version,status,currency,currency_exponent,monthly_minor,trial_days,staff_limit,staff_unlimited,clinic_limit,clinic_unlimited,over_limit_policy,renewal_policy,grace_days,expiry_policy,cancellation_policy,refund_policy,terms_document_ref,commercial_approval_ref,legal_approval_ref)
select pg_temp.id(53),'synthetic-zero',1,'approved',currency,currency_exponent,monthly_minor,trial_days,0,false,0,false,over_limit_policy,renewal_policy,grace_days,expiry_policy,cancellation_policy,refund_policy,'synthetic-zero/v1',commercial_approval_ref,legal_approval_ref from public.doctor_saas_terms_versions where id=pg_temp.id(51);
update public.doctor_saas_configuration set terms_version_id=pg_temp.id(53),revision=4,change_reason='Synthetic explicit zero limit offer';
set local role authenticated;select pg_temp.claim(3);
select public.doctor_start_saas_trial(pg_temp.id(53),4,'synthetic-zero/v1',pg_temp.id(63));
select throws_ok($$select pg_temp.command(format('select public.doctor_onboard(%L,%L,%L,%L)','Synthetic zero owner','Synthetic zero clinic','Etc/UTC',pg_temp.id(84)))$$,'DS003','DOCTOR_SAAS_CLINIC_LIMIT','explicit zero is not unlimited, including first-clinic onboarding');
reset role;
select is((select count(*)::integer from public.doctor_profiles where user_id=pg_temp.id(3)),0,'failed first-clinic allocation leaves no partial Doctor profile');
select is((select count(*)::integer from public.practices where owner_user_id=pg_temp.id(3)),0,'failed onboarding leaves no partial practice');
select ok(not exists(select 1 from doctor_private.command_receipts where command_key=pg_temp.id(84)),'failed onboarding leaves no success receipt');
insert into public.doctor_profiles(user_id,display_name)values(pg_temp.id(3),'Synthetic zero quota fixture');
insert into public.practices(id,owner_user_id,name)values(pg_temp.id(23),pg_temp.id(3),'Synthetic zero quota fixture');
select pg_temp.claim(3);
select throws_ok($$select pg_temp.command(format('insert into public.memberships(practice_id,user_id)values(%L,%L)',pg_temp.id(23),pg_temp.id(4)))$$,'DS002','DOCTOR_SAAS_STAFF_LIMIT','physical active allocation also enforces an explicit zero staff limit');
select is((select count(*)::integer from public.memberships where practice_id=pg_temp.id(23)),0,'failed physical membership allocation rolls back completely');
select * from finish();rollback;
